    | CancelPending
    | SetFrozenPrimary
    | SetFrozenBackup
    | EnterSafeMode
    | ResetSafeMode
    | ConfirmAlive
    | SetDirectForTest

/// Wallet also accepts callbacks from `OperationStorage`.
type MeraWalletAnyIncoming =
    | MeraWalletIncoming
